"""Shared fixtures — synthetic genomes only (never the private data/ files)."""

from __future__ import annotations

from pathlib import Path

import pytest


def _write_23andme(path: Path, rows: list[tuple[str, str, int, str]]) -> Path:
    lines = [
        "# This data file generated by 23andMe at: Mon Jan 01 00:00:00 2024",
        "# We are using reference human assembly build 37.",
        "# rsid\tchromosome\tposition\tgenotype",
    ]
    for rsid, chrom, pos, geno in rows:
        lines.append(f"{rsid}\t{chrom}\t{pos}\t{geno}")
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return path


SHARED_ROWS = [
    ("rs1801133", "1", 11856378, "AG"),
    ("rs4680", "22", 19951271, "GG"),
    ("rs762551", "15", 75041917, "AA"),
    ("rs9939609", "16", 53820527, "AT"),
    ("rs4988235", "2", 136608646, "CT"),
    ("rs12913832", "15", 28365618, "AG"),
    ("rs1815739", "11", 66328095, "CT"),
    ("rs429358", "19", 45411941, "TT"),
    ("rs7412", "19", 45412079, "CC"),
    ("rs713598", "7", 141672604, "CG"),
]


@pytest.fixture()
def synthetic_genome_a(tmp_path: Path) -> Path:
    return _write_23andme(tmp_path / "genome_A.txt", SHARED_ROWS)


@pytest.fixture()
def synthetic_genome_b(tmp_path: Path) -> Path:
    # Mostly identical with a few flips — enough for ingest/health; relatedness may find little IBD
    rows = list(SHARED_ROWS)
    rows[0] = ("rs1801133", "1", 11856378, "AA")
    rows[3] = ("rs9939609", "16", 53820527, "TT")
    return _write_23andme(tmp_path / "genome_B.txt", rows)


